/**
 * Claude brand mark — the radial "sunburst" in Anthropic's clay color, shown
 * wherever we surface the Claude AI Builder integration. Nominative use of a
 * third-party brand to indicate a real integration. If Anthropic's official
 * asset is preferred, drop it into /public and swap this out.
 */
export function ClaudeMark({ size = 22, className }: { size?: number; className?: string }) {
  // 12 tapered rays radiating from center, rounded ends — the Claude sunburst.
  const rays = Array.from({ length: 12 }, (_, i) => (i * 360) / 12);
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      className={className}
      aria-label="Claude"
      role="img"
    >
      <g fill="#D97757">
        {rays.map((deg) => (
          <rect
