};

/**
 * Renders a product/OS/app/game logo. Real brand SVGs live in /public/logos; the
 * chip has a light background so both colored and dark logos stay visible on the
 * dark UI. Falls back to a tasteful emoji or the first letter.
 */
export function AppLogo({ family, name, size = 32 }: { family: string; name?: string; size?: number }) {
  const box = { width: size, height: size, minWidth: size };
  if (HAS_LOGO.has(family)) {
    return (
      <span
        className="flex items-center justify-center rounded-lg border border-white/10 bg-white/90 p-1.5"
        style={box}
      >
        <img src={`/logos/${family}.svg`} alt={name ?? family} className="h-full w-full object-contain" />
      </span>
    );
  }
  return (
    <span
      className="flex items-center justify-center rounded-lg border border-white/10 bg-white/[0.06] text-base"
      style={box}
    >
      {FALLBACK[family] ?? (name ?? family).charAt(0).toUpperCase()}
