function logoFamily(name: string): string {
  const n = name.toLowerCase();
  const table: [string, string][] = [
    ["ubuntu", "ubuntu"], ["debian", "debian"], ["almalinux", "almalinux"],
    ["rocky", "rocky"], ["fedora", "fedora"], ["centos", "centos"], ["arch", "arch"],
    ["alpine", "alpine"], ["kali", "kali"], ["suse", "opensuse"],
    ["cpanel", "cpanel"], ["plesk", "plesk"], ["cyberpanel", "cyberpanel"],
    ["webmin", "webmin"], ["cloudpanel", "cloudpanel"], ["aapanel", "aapanel"],
    ["hestia", "hestiacp"],
    ["docker", "docker"], ["wordpress", "wordpress"], ["nextcloud", "nextcloud"],
    ["ghost", "ghost"], ["node", "nodejs"], ["caddy", "caddy"],
    ["wireguard", "wireguard"], ["openvpn", "openvpn"], ["gitea", "gitea"],
    ["jellyfin", "jellyfin"], ["pi-hole", "pihole"], ["pihole", "pihole"],
    ["grafana", "grafana"], ["portainer", "portainer"], ["vaultwarden", "vaultwarden"],
    ["uptime", "uptimekuma"],
  ];
  for (const [k, fam] of table) if (n.includes(k)) return fam;
