}

function Tile({ name }: { name: string }) {
  return (
    <div className="group flex items-center gap-3 rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-3 transition-all duration-200 hover:-translate-y-0.5 hover:border-brand-500/30 hover:bg-white/[0.05] hover:shadow-[0_8px_24px_-12px_rgb(111_71_245_/_0.5)]">
      <AppLogo family={logoFamily(name)} name={name} size={36} />
      <span className="truncate text-sm font-medium text-slate-200">{name}</span>
    </div>
  );
}

export function DeployCatalog({ groups }: { groups: CatalogGroup[] }) {
  const [active, setActive] = useState(groups[0]?.key ?? "");
  const current = groups.find((g) => g.key === active) ?? groups[0];

  return (
    <div className="card p-6 sm:p-8">
      <div className="flex flex-wrap justify-center gap-2">
        {groups.map((g) => (
          <button
            key={g.key}
            onClick={() => setActive(g.key)}
            className={`rounded-xl px-4 py-2 text-sm font-semibold transition-all ${
              g.key === current?.key
                ? "bg-gradient-to-r from-accent-blue to-brand-500 text-white shadow-lg"
                : "border border-white/10 bg-white/[0.03] text-slate-400 hover:text-white"
            }`}
          >
            {g.label}
            <span className="ml-2 text-xs opacity-70">{g.items.length}</span>
          </button>
        ))}
      </div>

      <div key={current?.key} className="mt-6 flex flex-wrap justify-center gap-3">
        {current?.items.map((item, i) => (
          <div
            key={item}
            className="nx-cat-tile w-full sm:w-[calc(50%-0.375rem)] lg:w-[calc(33.333%-0.5rem)]"
            style={{ animationDelay: `${i * 35}ms` }}
          >
            <Tile name={item} />
          </div>
        ))}
      </div>

      <style>{`
        .nx-cat-tile { animation: nx-cat-in 0.4s cubic-bezier(0.22,1,0.36,1) both; }
        @keyframes nx-cat-in { from { opacity: 0; transform: translateY(10px) scale(0.98); } to { opacity: 1; transform: none; } }
        @media (prefers-reduced-motion: reduce) { .nx-cat-tile { animation: none !important; } }
      `}</style>
    </div>
  );
}

