/* eslint-disable @next/next/no-img-element */
import { Reveal } from "./Reveal";
import { Section, SectionTitle } from "./primitives";
import { ClaudeMark } from "./ClaudeMark";

/**
 * "Works with your stack" — an infinite, seamless logo marquee of the
 * technologies Nxeon actually runs on and integrates with.
 *
 * HONESTY: every entry below is a REAL integration in this codebase (the
 * `why` note on each item records the evidence). Nothing here is a customer,
 * client, partner, investor or endorsement — the copy and the footnote say so
 * explicitly. Nominative use only, to identify the technology.
 *
 * ASSETS: brands with a real SVG in /public/logos render their mark; brands
 * without one render a clean text wordmark in the design system's type rather
 * than us pulling third-party logo files into the repo. The uniform monochrome
 * treatment makes the mix read as deliberate.
 *
 * TECHNIQUE: pure CSS. The track holds the list twice (the second copy is
 * `aria-hidden`) and animates `translate3d(0)` → `translate3d(-50%)`. Because
 * ALL spacing lives in each item's `margin-inline-end` (never a flex `gap` on
 * the track), the two halves are exactly equal width, so -50% lands one full
 * list over and the loop is gapless. No JS ticker, no deps.
 */

type Mark = {
  /** Display name — doubles as the accessible label. */
  name: string;
  /** Basename of an existing /public/logos/*.svg. Omit → text wordmark. */
  logo?: string;
  /** Use the inline ClaudeMark component instead of an <img>. */
  claude?: boolean;
  /** Evidence that the integration is real (kept in source, not rendered). */
  why: string;
};

/** Row 1 — the platform Nxeon itself is built on. */
const PLATFORM: Mark[] = [
  { name: "Proxmox", why: "lib/proxmox.ts — the hypervisor layer every VPS is provisioned through" },
  { name: "Cloudflare", why: "lib/cloudflare-dns.ts + lib/cloudflare-oauth.ts + app/api/integrations/cloudflare/*" },
  { name: "Stripe", why: "lib/stripe.ts + app/api/stripe/{checkout,confirm,webhook}" },
  { name: "Claude", claude: true, why: "lib/anthropic.ts (Messages API) + lib/ai-build.ts (AI builder)" },
  { name: "Docker", logo: "docker", why: "lib/cpanel-types.ts service unit + worker/migrate-real.ts compose bring-up" },
  { name: "Let's Encrypt", why: "worker/websites.ts runs certbot --nginx; worker/ssl.ts issues the certs" },
  { name: "nginx", why: "worker/websites.ts nginxVhost()/ensureNginx()" },
  { name: "Apache", why: "worker/migrate-real.ts installs + enables apache2/httpd vhosts on migration" },
  { name: "MariaDB", why: "worker/databases.ts ensureMysql() installs mariadb-server" },
  { name: "MySQL", why: "worker/databases.ts ensureMysql() default-mysql-server; migrate-real PkgKey" },
  { name: "PostgreSQL", why: "worker/databases.ts ensurePostgres()" },
  { name: "Redis", logo: undefined, why: "lib/cpanel-types.ts redis-server service + worker/migrate-detect.ts" },
  { name: "Node.js", logo: "nodejs", why: "one-click app image + worker/migrate-real.ts nodejs prereq" },
  { name: "Name.com", why: "lib/registrar.ts — the domain registrar behind search/register/transfer" },
  { name: "Ubuntu", logo: "ubuntu", why: "OS template" },
  { name: "Debian", logo: "debian", why: "OS template" },
];

/** Row 2 — what you can deploy on it. */
const STACK: Mark[] = [
  { name: "WordPress", logo: "wordpress", why: "worker/apps.ts one-click install (lib/cpanel-types.ts slug)" },
  { name: "Ghost", logo: "ghost", why: "worker/apps.ts one-click install" },
  { name: "Nextcloud", logo: "nextcloud", why: "worker/apps.ts one-click install" },
  { name: "cPanel", logo: "cpanel", why: "control-panel template" },
  { name: "Plesk", logo: "plesk", why: "control-panel template" },
  { name: "Portainer", logo: "portainer", why: "one-click app image" },
  { name: "Grafana", logo: "grafana", why: "one-click app image" },
  { name: "Gitea", logo: "gitea", why: "one-click app image" },
  { name: "Jellyfin", logo: "jellyfin", why: "one-click app image" },
  { name: "Caddy", logo: "caddy", why: "one-click app image" },
  { name: "WireGuard", logo: "wireguard", why: "one-click app image" },
  { name: "OpenVPN", logo: "openvpn", why: "one-click app image" },
  { name: "Pi-hole", logo: "pihole", why: "one-click app image" },
  { name: "Vaultwarden", logo: "vaultwarden", why: "one-click app image" },
  { name: "Uptime Kuma", logo: "uptimekuma", why: "one-click app image" },
  { name: "AlmaLinux", logo: "almalinux", why: "OS template" },
  { name: "Rocky Linux", logo: "rocky", why: "OS template" },
  { name: "Fedora", logo: "fedora", why: "OS template" },
  { name: "Alpine", logo: "alpine", why: "OS template" },
  { name: "Arch Linux", logo: "arch", why: "OS template" },
  { name: "Minecraft", logo: "minecraft", why: "lib/game-config.ts MINECRAFT family + worker/game-update.ts" },
  { name: "Steam", logo: "steam", why: "worker/game-update.ts steamcmd app_update for Rust/Valheim/CS2/Palworld" },
];

/**
 * One item. The mark is decorative (`alt=""`): the visible name right next to
 * it already carries the accessible name, so labelling both would make screen
 * readers announce every brand twice.
 */
function Item({ m }: { m: Mark }) {
  return (
    <li className="nx-marq-item">
      {(m.logo || m.claude) && (
        <span className="nx-marq-mark">
          {m.claude ? (
            <ClaudeMark size={22} />
          ) : (
            <img src={`/logos/${m.logo}.svg`} alt="" aria-hidden="true" loading="lazy" decoding="async" />
          )}
        </span>
      )}
      <span className="nx-marq-label">{m.name}</span>
    </li>
  );
}

function Row({ items, reverse = false, dur }: { items: Mark[]; reverse?: boolean; dur: string }) {
  return (
    <div className={`nx-marq-row ${reverse ? "nx-marq-rev" : ""}`}>
