        <ul className="nx-marq-list nx-marq-dup" aria-hidden="true">
          {items.map((m) => (
            <Item key={m.name} m={m} />
          ))}
        </ul>
      </div>
    </div>
  );
}

export function LogoMarquee() {
  return (
    <Section tone="base" size="sm">
      <SectionTitle
        eyebrow="Works with your stack"
        title="Integrates with the tools you already use"
        sub="The platforms Nxeon runs on, and the software you can deploy in one click."
      />

      <Reveal className="mt-10">
        <div className="nx-marq" role="group" aria-label="Technologies Nxeon integrates with and runs">
          <Row items={PLATFORM} dur="58s" />
          <Row items={STACK} reverse dur="72s" />
        </div>

        <p className="mx-auto mt-8 max-w-2xl text-center text-xs leading-relaxed text-slate-500">
          All names and logos are the trademarks of their respective owners, shown only to identify
          the technologies Nxeon integrates with or runs. No affiliation, partnership, sponsorship
          or endorsement is implied.
        </p>
      </Reveal>

      <style>{`
        .nx-marq { display: flex; flex-direction: column; gap: 0.875rem; }

        /* Edge fade so logos dissolve at the rails instead of hard-cutting. */
        .nx-marq-row {
          overflow: hidden;
          -webkit-mask-image: linear-gradient(to right, transparent 0, #000 9%, #000 91%, transparent 100%);
          mask-image: linear-gradient(to right, transparent 0, #000 9%, #000 91%, transparent 100%);
        }

        /* The only moving part: one composited transform, no layout, no JS. */
        .nx-marq-track {
          display: flex;
          width: max-content;
          will-change: transform;
          animation: nx-marq-scroll var(--nx-marq-dur, 60s) linear infinite;
        }
        .nx-marq-rev .nx-marq-track { animation-direction: reverse; }
        .nx-marq-row:hover .nx-marq-track,
        .nx-marq-row:focus-within .nx-marq-track { animation-play-state: paused; }

        @keyframes nx-marq-scroll {
          from { transform: translate3d(0, 0, 0); }
          to   { transform: translate3d(-50%, 0, 0); }
        }

        /* NOTE: no flex gap here — all spacing is the item's margin-inline-end,
           which is what keeps the two halves exactly equal and the seam invisible. */
        .nx-marq-list { display: flex; margin: 0; padding: 0; list-style: none; }

        .nx-marq-item {
          display: inline-flex;
          align-items: center;
          gap: 0.55rem;
          margin-inline-end: 0.75rem;
          padding: 0.5rem 0.9rem;
          border-radius: 9999px;
          border: 1px solid rgb(255 255 255 / 0.06);
          background: rgb(255 255 255 / 0.02);
          white-space: nowrap;
          transition: background-color 0.3s ease, border-color 0.3s ease;
        }
        .nx-marq-item:hover {
          border-color: rgb(111 71 245 / 0.32);
          background: rgb(255 255 255 / 0.05);
        }

        .nx-marq-mark {
          display: flex;
          align-items: center;
          justify-content: center;
          height: 1.75rem;
          width: 1.75rem;
          flex: none;
          border-radius: 0.5rem;
          background: rgb(255 255 255 / 0.07);
          transition: background-color 0.3s ease;
        }
        .nx-marq-mark img,
        .nx-marq-mark svg {
          height: 1.05rem;
          width: 1.05rem;
          object-fit: contain;
          /* Monochrome at rest: flatten every mark to white so dark logos
             (Ghost) stay legible on navy and the strip reads as one calm row. */
          filter: grayscale(1) brightness(0) invert(1);
          opacity: 0.6;
          transition: filter 0.3s ease, opacity 0.3s ease;
        }
        .nx-marq-item:hover .nx-marq-mark { background: rgb(255 255 255 / 0.92); }
        .nx-marq-item:hover .nx-marq-mark img,
        .nx-marq-item:hover .nx-marq-mark svg { filter: none; opacity: 1; }

        .nx-marq-label {
          font-size: 0.8125rem;
          font-weight: 600;
          letter-spacing: -0.005em;
          color: rgb(148 163 184);
          opacity: 0.75;
          transition: color 0.3s ease, opacity 0.3s ease;
        }
        .nx-marq-item:hover .nx-marq-label { color: #fff; opacity: 1; }

        /* Mobile: smaller chips and a quicker loop so it never feels stalled. */
        @media (max-width: 640px) {
          .nx-marq-track { animation-duration: calc(var(--nx-marq-dur, 60s) * 0.62); }
          .nx-marq-item { margin-inline-end: 0.5rem; padding: 0.4rem 0.7rem; gap: 0.45rem; }
          .nx-marq-mark { height: 1.5rem; width: 1.5rem; border-radius: 0.4rem; }
          .nx-marq-mark img, .nx-marq-mark svg { height: 0.95rem; width: 0.95rem; }
          .nx-marq-label { font-size: 0.75rem; }
        }

        /* Reduced motion: no animation at all. Drop the duplicate track and the
           edge masks, and let the real list wrap into a static centered grid. */
        @media (prefers-reduced-motion: reduce) {
          .nx-marq { gap: 0.5rem; }
          .nx-marq-row {
            overflow: visible;
            -webkit-mask-image: none;
            mask-image: none;
          }
          .nx-marq-track {
            animation: none;
            transform: none;
            width: 100%;
            will-change: auto;
            justify-content: center;
          }
          .nx-marq-dup { display: none; }
          .nx-marq-list { flex-wrap: wrap; justify-content: center; }
          .nx-marq-item { margin-inline-end: 0; margin: 0.25rem; }
        }
      `}</style>
    </Section>
  );
}
